/** Named Sale's router: the asset's format, drawn by the chosen board design
 *  (designs.ts, generated by the template lab) -- the asset's own
 *  choice, else the format's first. A send's email header is its email's
 *  hero section, drawn under the email's own ids: one set of edits for both. */
import type { SheetAsset } from '../../../sheet/types';
import { FigmaBand } from '../../figma/FigmaLayers';
import { DESIGNS } from './designs';
import { COMPONENTS } from './components';
import { sectionOf } from './sections';
import { sectionName } from '../../emailSections';

/** Whether the board has a design for this format. */
export const namedSaleHas = (format: string) => DESIGNS.some(d => d.format === format);

export function NamedSale({ asset, design }: { asset: SheetAsset; design?: string }) {
  if (asset.format === 'email-hero') return <NamedSaleHero asset={asset} design={design} />;
  const list = DESIGNS.filter(d => d.format === asset.format);
  const d = list.find(x => x.id === design) ?? list[0];
  const Design = d && COMPONENTS[d.component];
  if (Design && asset.format === 'email-body' && asset.parts) return <NamedSaleEmail asset={asset} width={d.size[0]} />;
  return Design ? <Design asset={asset} /> : <div className="gap">no Named Sale design for {asset.format}</div>;
}

/** A send's email header: its email design's hero section (one band of the
 *  email), as the email draws it -- keyed as the send's email, so a photo,
 *  a logo or a line changed in one is changed in the other. */
function NamedSaleHero({ asset, design }: { asset: SheetAsset; design?: string }) {
  const list = DESIGNS.filter(d => d.format === 'email-body');
  const d = list.find(x => x.id === design) ?? list[0];
  const Design = d && COMPONENTS[d.component], hero = d?.sections?.find(s => s.kind === 'hero');
  if (!Design || !hero) return <div className="gap">no Named Sale email for this header</div>;
  const email = { ...asset, id: `email-body${asset.id.slice('email-hero'.length)}`, format: 'email-body' };
  return <div className="sheet" data-figma-compiled="" style={{ width: d.size[0], position: 'relative', background: '#fff' }}>
    <FigmaBand.Provider value={{ ...hero, name: sectionName(hero) }}><Design asset={email} /></FigmaBand.Provider>
  </div>;
}

/** An email built of sections: each its design drawn as one band (FigmaBand),
 *  stacked. A section's own key gives its slots ids of their own. */
function NamedSaleEmail({ asset, width }: { asset: SheetAsset; width: number }) {
  return <div className="sheet" data-figma-compiled="" style={{ width, position: 'relative', background: '#fff' }}>
    {asset.parts!.map((p, n) => {
      if (p.off) return null;
      const d = DESIGNS.find(x => x.format === 'email-body' && x.id === p.design), s = sectionOf(p);
      const Design = d && COMPONENTS[d.component];
      // data-part: where the section starts, for the Sections list to scroll to.
      return Design && s ? <FigmaBand.Provider key={p.key || `${p.design}.${p.section}`} value={{ ...s, name: sectionName(s), heading: p.heading }}>
        <div data-part={n} />
        <Design asset={p.key ? { ...asset, id: `${asset.id}~${p.key}` } : asset} />
      </FigmaBand.Provider> : null;
    })}
  </div>;
}
